    /**
     * Method to retrieve the InventoryTransaction via an InventoryTransactionPrimaryKey.
     * @param 	id Long
     * @return 	InventoryTransaction
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public InventoryTransaction handle( FindInventoryTransactionQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getInventoryTransactionId() );
    }
    
    /**
     * Method to retrieve a collection of all InventoryTransactions
     *
     * @param	query	FindAllInventoryTransactionQuery 
     * @return 	List<InventoryTransaction> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<InventoryTransaction> handle( FindAllInventoryTransactionQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindInventoryTransaction,
 * but only if the id matches
 *
 * @param		entity	InventoryTransaction
 */
	protected void emitFindInventoryTransaction( InventoryTransaction entity ) {
		LOGGER.info("handling emitFindInventoryTransaction" );
		
	    queryUpdateEmitter.emit(FindInventoryTransactionQuery.class,
	                            query -> query.getFilter().getInventoryTransactionId().equals(entity.getInventoryTransactionId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllInventoryTransaction
	 * 
	 * @param		entity	InventoryTransaction
	 */
	protected void emitFindAllInventoryTransaction( InventoryTransaction entity ) {
		LOGGER.info("handling emitFindAllInventoryTransaction" );
		
	    queryUpdateEmitter.emit(FindAllInventoryTransactionQuery.class,
	                            query -> true,
	                            entity);
	}

